// ISR: regenerate at most once every 5 minutes
// (replaces `revalidate: 300` from getStaticProps)
export const revalidate = 300

// Params not returned by generateStaticParams are rendered on demand
// (replaces `fallback: 'blocking'` from getStaticPaths)
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPostData(
  id: string
): Promise<{ post: Post; comments: Comment[] }> {
  const [post, comments] = await Promise.all([
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}`).then((res) => {
      if (!res.ok) notFound()
      return res.json() as Promise<Post>
    }),
    fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`).then(
      (res) => {
        if (!res.ok) notFound()
        return res.json() as Promise<Comment[]>
      }
    ),
  ])

  return { post, comments }
}

